order(s,[U],['je-voudrais','beurre','et','confiture','sil-vous-plait'],[],'Соберите «Мне бы хотелось масла и варенья, пожалуйста». Начните с вежливой рамки и сохраните этот порядок продуктов.',[('Je voudrais','жё вудрэ́'),('du beurre','дю бё́р'),('et de la confiture,','э дё ла ко(н)фитю́р'),('s’il vous plaît.','силь ву плэ́')],'Je voudrais du beurre et de la confiture, s’il vous plaît.','жё вудрэ дю бёр э дё ла ко(н)фитюр, силь ву плэ́.','Получилась просьба о двух продуктах с показанными формами.','Поставьте вежливую рамку первой, затем масло, варенье и пожалуйста.')
page(s,[('Сделать заказ и завтракать',['Заказывать завтрак и уже завтракать — разные действия. В этой теме новая форма обозначает именно заказ.'],[W['commander']['example']]),('Продукт без точной меры',['В просьбах показаны сочетания с маслом, вареньем и молоком. Изучаются эти случаи частичного артикля; полная таблица исключений не требуется.'],[W['beurre']['example'],W['confiture']['example'],W['lait']['example']]),('Вежливая рамка',['Готовая форма просьбы сохраняется. Меняйте нужный продукт, сохраняя показанное сочетание с ним.'],[ex('Je voudrais du lait et de l’eau.','Мне бы хотелось молока и воды.','жё вудрэ дю лэ э дё ло́')])])
